import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    original_edges = []

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        original_edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    degrees = [0] * (n + 1)
    for u in range(1, n + 1):
        degrees[u] = len(adj[u])

    added_edges = []

    stack = []
    for i in range(1, n + 1):
        if degrees[i] % 2 != 0:
            stack.append(i)

    while stack:
        u = stack.pop()
        if degrees[u] % 2 == 0:
            continue

        found_v = -1
        for v in adj[u]:
            if degrees[v] % 2 != 0:
                found_v = v
                break

        if found_v != -1:
            added_edges.append((u, found_v))
            degrees[u] += 1
            degrees[found_v] += 1
            adj[u].append(found_v)
            adj[found_v].append(u)
        else:
            added_edges.append((u, u))
            degrees[u] += 2
            adj[u].append(u)
            adj[u].append(u)

    visited = [False] * (n + 1)
    result_edges = []

    for start_node in range(1, n + 1):
        if visited[start_node]:
            continue

        q = deque([start_node])
        visited[start_node] = True

        while q:
            u = q.popleft()

            idx = 0
            while idx < len(adj[u]):
                v = adj[u][idx]

                if not visited[v]:
                    visited[v] = True
                    result_edges.append((u, v))
                    q.append(v)
                else:
                    if not visited[u]:
                        visited[u] = True
                        result_edges.append((v, u))
                    else:
                        result_edges.append((u, v))

                idx += 1

    print(len(result_edges))
    for u, v in result_edges:
        print(f"{u} {v}")

if __name__ == "__main__":
    main()
